      "path": "index.js",
      "content": "import { detectWsl } from \"./lib/wsl-host.js\";\nimport * as core from \"./lib/wininput.js\";\nimport { execute } from \"./lib/wininput-exec.js\";\n\nexport const name = \"dsh-wsl-wininput\";\nexport const inject = [\"tools\", \"systemPrompt\"];\n\nexport function apply(ctx, config = {}) {\n  const wsl = detectWsl();\n\n  ctx.systemPrompt.section({\n    name: \"tool:win_invoke\",\n    order: 211,\n    text: \"Use win_invoke to act on Windows UI from WSL. action=invoke activates a UI Automation element by the handle uia_tree returned; the element is re-checked before it is invoked, so a handle from an older observation fails instead of clicking the wrong control. action=type and action=click target a window by pid.\",\n  });\n\n  ctx.tools.register({\n    name: \"win_invoke\",\n    description: \"Targeted Windows input from WSL: invoke a UI Automation element by handle, type text into a window, or click a window-relative point.\",\n    parameters: core.parameters(),\n    output: {\n      schema: core.outputSchema(),\n      render: (_args, value) => [{ type: \"text\", text: core.format(value) }],\n    },\n    timeoutMs: Number(config.timeoutMs) > 0 ? Number(config.timeoutMs) : 30_000,\n    isConcurrencySafe: () => false,\n    async execute(args) {\n      if (!wsl) return { ok: false, action: args?.action ?? \"invoke\", error: \"not running in WSL\" };\n      try {\n        return await execute(args, config);\n      } catch (error) {\n        return { ok: false, action: args?.action ?? \"invoke\", error: String(error?.message ?? error) };\n      }\n    },\n    presentCall: (args) => ({ card: \"generic\", title: `win_invoke ${args?.action ?? \"invoke\"}` }),\n    presentResult: (_args, result) => ({ card: \"generic\", title: \"win_invoke\", content: result?.content }),\n  });\n}\n"
    },
    {
      "path": "lib/wininput.js",
      "content": "// Targeted input. The whole point is that nothing here acts on \"whatever is\n// focused\": every action names a window, and an element action re-checks that\n// the element it was told about is still the element it finds.\nexport const ACTIONS = [\"invoke\", \"type\", \"key\", \"click\", \"scroll\"];\n\nexport function assertAction(action) {\n  if (!ACTIONS.includes(action)) {\n    throw new Error(`unsupported action: ${String(action)} (expected one of ${ACTIONS.join(\", \")})`);\n  }\n  return action;\n}\n\nexport function safeInt(v, fallback = 0) {\n  const n = Number(v);\n  return Number.isFinite(n) ? Math.trunc(n) : fallback;\n}\n\nexport function parseHandle(handle) {\n  if (typeof handle !== \"string\") return null;\n  const m = /^(\\d+)\\.(\\d+)$/.exec(handle.trim());\n  return m ? { epoch: Number(m[1]), index: Number(m[2]) } : null;\n}\n\n/**\n * An element action is accepted only if the element found at the handle's index\n * still looks like the one the caller saw. Comparing name and control type is\n * what makes a handle from an earlier observation detectable: if the list moved,\n * or the button was replaced, this fails instead of clicking the wrong thing.\n */\nexport function sameElement(observed, current) {\n  if (!observed || !current) return false;\n  if (String(observed.controlType ?? \"\") !== String(current.controlType ?? \"\")) return false;\n  if (String(observed.name ?? \"\") !== String(current.name ?? \"\")) return false;\n  return true;\n}\n\nexport function format(v) {\n  const lines = [`win_invoke ok=${v.ok} action=${v.action}`];\n  if (v.window) lines.push(`  window: pid=${v.window.pid} \"${v.window.title}\"`);\n  if (v.element) lines.push(`  element: ${v.element.controlType} \"${v.element.name}\"`);\n  if (v.text) lines.push(`  typed: ${JSON.stringify(v.text)}`);\n  if (v.sequence) lines.push(`  sequence: ${v.sequence}`);\n  if (v.scrolled) lines.push(`  scrolled: ${v.scrolled}`);\n  if (v.point) lines.push(`  point: